import re
import torch


def words(text):
    return re.findall(r"[a-z]+", text.lower())


def vectorize(text, vocab):
    found = words(text)
    return torch.tensor([float(found.count(word)) for word in vocab])


def retrieve(question, docs, k=1):
    vocab = sorted({word for doc in docs for word in words(doc)})
    matrix = torch.stack([vectorize(doc, vocab) for doc in docs])
    query = vectorize(question, vocab)
    scores = matrix @ query / (matrix.norm(dim=1) * query.norm() + 1e-9)
    order = scores.argsort(descending=True)[:k]
    return [docs[i] for i in order.tolist()]

