def probabilities(logits, temperature=1.0):
    return torch.softmax(logits / temperature, dim=-1)


def top_k(logits, k):
    kept = logits.clone()
    threshold = logits.topk(k).values[-1]
    kept[logits < threshold] = float("-inf")
    return kept


def sample(logits, temperature=1.0, k=None, generator=None):
    if k is not None:
        logits = top_k(logits, k)
    p = probabilities(logits, temperature)
    return int(torch.multinomial(p, 1, generator=generator))

